"use client";

import { useEffect, useMemo, useState } from "react";
import { motion, AnimatePresence } from "framer-motion";
import { MoveRight } from "lucide-react";
import Link from "next/link";
import { Button } from "@/components/ui/button";
import AnimatedGradient from "@/components/ui/animated-gradient";

export default function Hero() {
  const [titleNumber, setTitleNumber] = useState(0);

  // Rotating words — the services we offer
  const titles = useMemo(
    () => ({
      en: ["Websites", "Brands", "Social Media", "Productions", "CGI"],
      ar: ["مواقع إلكترونية", "علامات تجارية", "سوشيال ميديا", "إنتاج إبداعي", "تصميم ثلاثي الأبعاد"],
    }),
    []
  );

  useEffect(() => {
    const timeoutId = setTimeout(() => {
      setTitleNumber((prev) =>
        prev === titles.en.length - 1 ? 0 : prev + 1
      );
    }, 2500);
    return () => clearTimeout(timeoutId);
  }, [titleNumber, titles]);

  // Detect language from html dir attribute
  const [lang, setLang] = useState<"ar" | "en">("ar");
  useEffect(() => {
    const checkLang = () => {
      setLang(document.documentElement.lang === "en" ? "en" : "ar");
    };
    checkLang();
    const observer = new MutationObserver(checkLang);
    observer.observe(document.documentElement, { attributes: true, attributeFilter: ["lang"] });
    return () => observer.disconnect();
  }, []);

  const currentTitles = titles[lang];

  return (
    <section className="relative isolate w-full min-h-screen flex items-center justify-center overflow-hidden">
      {/* Animated gradient background */}
      <AnimatedGradient
        config={{
          preset: "custom",
          color1: "#01080f",
          color2: "#050f2a",
          color3: "#7bbbff",
          rotation: -50,
          proportion: 35,
          scale: 0.5,
          speed: 20,
          distortion: 3,
          swirl: 50,
          swirlIterations: 10,
          softness: 80,
          offset: -200,
          shape: "Checks",
          shapeSize: 30,
        }}
        noise={{ opacity: 0.15, scale: 1 }}
        style={{ zIndex: 0 }}
      />

      {/* Content */}
      <div className="container mx-auto relative z-10">
        <div className="flex gap-8 py-20 lg:py-40 items-center justify-center flex-col">
          {/* Headline with rotating words */}
          <div className="flex gap-4 flex-col">
            <h1 className="text-5xl md:text-7xl max-w-3xl tracking-tighter text-center font-bold">
              <span>
                {lang === "ar" ? "نبني تجارب رقمية تصنع" : "We Build Digital Experiences That Drive"}
              </span>
              <span className="relative flex w-full justify-center overflow-hidden text-center md:pb-4 md:pt-1 min-h-[1.5em] items-center">
                <AnimatePresence mode="wait">
                  <motion.span
                    key={`${lang}-${titleNumber}`}
                    className="font-semibold text-brand-primary"
                    initial={{ opacity: 0, y: 50 }}
                    animate={{ opacity: 1, y: 0 }}
                    exit={{ opacity: 0, y: -50 }}
                    transition={{ type: "spring", stiffness: 100, damping: 20 }}
                  >
                    {currentTitles[titleNumber]}
                  </motion.span>
                </AnimatePresence>
              </span>
            </h1>

            <p className="text-lg md:text-xl leading-relaxed tracking-tight text-white max-w-2xl text-center mx-auto">
              {lang === "ar"
                ? "مواقع مخصصة، هوية بصرية، إدارة سوشيال ميديا، و CGI سينمائي — مصممة للشركات الجاهزة للتميّز في سوقها."
                : "Custom websites, brand identity, social media, and cinema-grade CGI — engineered for businesses ready to dominate their market."}
            </p>
          </div>

          {/* CTA buttons */}
          <div className="flex flex-row gap-3">
            <Link href="/contact">
              <Button size="lg" className="gap-3 rounded-full">
                {lang === "ar" ? "ابدأ مشروعك" : "Start Your Project"}
                <MoveRight className="w-4 h-4" />
              </Button>
            </Link>
            <Link href="/portfolio">
              <Button size="lg" variant="outline" className="gap-3 rounded-full">
                {lang === "ar" ? "شاهد أعمالنا" : "View Our Work"}
              </Button>
            </Link>
          </div>
        </div>
      </div>
    </section>
  );
}
